from datetime import datetime, timedelta, date

# Use existing venmo_token from prior execution
print('venmo_token exists:', 'venmo_token' in globals(), bool(venmo_token))

all_requests = []
page_index = 0
while True:
    resp = apis.venmo.show_received_payment_requests(access_token=venmo_token, page_index=page_index)
    # Determine shape
    if isinstance(resp, dict):
        # Some APIs might wrap results
        if 'results' in resp:
            page_reqs = resp['results']
        elif 'data' in resp:
            page_reqs = resp['data']
        else:
            # try common key
            page_reqs = resp.get('items', [])
    else:
        page_reqs = resp

    if not page_reqs:
        print('No more results at page_index', page_index)
        break

    print('page_index', page_index, 'page_count', len(page_reqs))
    all_requests.extend(page_reqs)
    page_index += 1

print('total_requests_fetched:', len(all_requests))

# Show one sample item
if all_requests:
    print('sample_keys:', list(all_requests[0].keys()))
    print('sample_item:', all_requests[0])

# Filter by created_at date in last 5 days including today
# start_date and end_date were set in prior code
start_dt = datetime.combine(start_date, datetime.min.time())
end_dt = datetime.combine(end_date, datetime.max.time())

matched = []
for r in all_requests:
    ca = r.get('created_at')
    # parse iso
    try:
        created = datetime.fromisoformat(ca.replace('Z','+00:00'))
    except Exception:
        continue
    if start_dt <= created <= end_dt:
        matched.append(r)

print('matched_requests_last5days:', len(matched))
if matched:
    # show min/max created_at
    created_dates = [datetime.fromisoformat(r['created_at'].replace('Z','+00:00')) for r in matched]
    print('created_at range:', min(created_dates), max(created_dates))

# Sum amounts
from decimal import Decimal

def to_decimal(x):
    try:
        return Decimal(str(x))
    except Exception:
        return Decimal('0')

amount_sum = sum((to_decimal(r.get('amount', 0.0)) for r in matched), Decimal('0'))
